export type uploadMediaResponse = (uploadMediaResponseSuccess | uploadMediaResponseError)

export const getUploadMediaUrl = (id: string,
    name: string,) => {




  return `/v1/posts/${id}/media/${name}`
}

/**
 * Stores an image the post's Markdown references as media/<slug>/<name>. Sending the same name again replaces it. Tokens add images to drafts only (403 live_post).
 */
export const uploadMedia = async (id: string,
    name: string,
    uploadMediaBody: Blob, options?: Parameters<typeof cmsFetch>[1]): Promise<uploadMediaResponse> => {

  return cmsFetch<uploadMediaResponse>(getUploadMediaUrl(id,name),
  {
    ...options,
    method: 'PUT',
    headers: getHeaders({ 'Content-Type': 'image/png' }, options?.headers),
    body: uploadMediaBody
  }
);}





export const getUploadMediaMutationKey = () => ['uploadMedia'] as const;

export const getUploadMediaMutationOptions = <TError = Error,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof uploadMedia>>, TError,UploadMediaMutationVariables, TContext>, request?: SecondParameter<typeof cmsFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof uploadMedia>>, TError,UploadMediaMutationVariables, TContext> => {

const mutationKey = getUploadMediaMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof uploadMedia>>, UploadMediaMutationVariables> = (props) => {
          const {id,name,data} = props ?? {};

          return  uploadMedia(id,name,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type UploadMediaMutationResult = NonNullable<Awaited<ReturnType<typeof uploadMedia>>>
    export type UploadMediaMutationBody = Blob
    export type UploadMediaMutationError = Error
    export type UploadMediaMutationVariables = {id: string;name: string;data: Blob}

    /** Stores an image the post's Markdown references as media/<slug>/<name>. Sending the same name again replaces it. Tokens add images to drafts only (403 live_post). */
export const useUploadMedia = <TError = Error,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof uploadMedia>>, TError,UploadMediaMutationVariables, TContext>, request?: SecondParameter<typeof cmsFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof uploadMedia>>,
        TError,
        UploadMediaMutationVariables,
        TContext
      > => {
      return useMutation(getUploadMediaMutationOptions(options), queryClient);
    }

